import json
with open('crypto_state.json') as f:
    state = json.load(f)
# Show open positions details
for k in ['open_positions', 'positions']:
    v = state.get(k, {})
    if v:
        print(f'{k}:')
        if isinstance(v, list):
            for p in v:
                print(f'  {p.get(\"symbol\",\"?\")}: entry={p.get(\"entry_price\")} amount={p.get(\"amount\")} margin={p.get(\"margin\")} notional={p.get(\"notional\")} is_closed={p.get(\"is_closed\",\"?\")}')
        elif isinstance(v, dict):
            for sym, p in v.items():
                print(f'  {sym}: {json.dumps(p, indent=4)[:200]}')
        else:
            print(f'  {v}')
" 2>&1

